import * as THREE from 'three';
// Dark depth-tinted base + 3-octave analytic normal chop (no displacement, no geometry bands).
const SHALLOW = new THREE.Color(0x2b3324), DEEP = new THREE.Color(0x141a10);
export function makeWater(size = 200) {
  const geo = new THREE.PlaneGeometry(size, size, 1, 1); geo.rotateX(-Math.PI / 2);
  const mat = new THREE.MeshStandardMaterial({ color: SHALLOW, roughness: 0.35, metalness: 0.0, envMapIntensity: 0.3 });
  mat.onBeforeCompile = (s) => {
    s.uniforms.uTime = { value: 0 }; s.uniforms.uDeep = { value: DEEP }; mat.userData.shader = s;
    s.vertexShader = 'varying vec3 vWp;\n' + s.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nvWp = (modelMatrix * vec4(position, 1.0)).xyz;');
    s.fragmentShader = 'uniform float uTime; uniform vec3 uDeep; varying vec3 vWp;\n' + s.fragmentShader
      .replace('#include <normal_fragment_maps>', [
        'float w1 = 6.2832 / 4.0, w2 = 6.2832 / 1.0, w3 = 6.2832 / 0.25;   // wavelengths 4 m / 1 m / 0.25 m: 16:1 span',
        'float dx = 0.04 * w1 * cos(vWp.x * w1 + uTime * 0.6) + 0.015 * w2 * cos((vWp.x * 0.7 + vWp.z * 0.7) * w2 - uTime * 1.3) + 0.004 * w3 * cos(vWp.z * w3 + uTime * 2.9);',
        'float dz = 0.04 * w1 * cos(vWp.z * w1 - uTime * 0.5) + 0.015 * w2 * cos((vWp.z * 0.7 - vWp.x * 0.7) * w2 + uTime * 1.1) + 0.004 * w3 * cos(vWp.x * w3 - uTime * 2.4);',
        'normal = normalize(mat3(viewMatrix) * vec3(-dx, 1.0, -dz));          // amplitudes in cm become slopes, not vertex steps'
      ].join('\n'))
      .replace('#include <color_fragment>', '#include <color_fragment>\nfloat depthT = smoothstep(0.0, 40.0, length(vWp.xz - cameraPosition.xz));\ndiffuseColor.rgb = mix(diffuseColor.rgb, uDeep, depthT);');
  };
  const mesh = new THREE.Mesh(geo, mat); mesh.userData.tag = 'water';
  return mesh;
}
export function tickWater(mesh, t) { const s = mesh.material.userData.shader; if (s) s.uniforms.uTime.value = t; }
